import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] first = br.readLine().trim().split("\\s+");
        int n = Integer.parseInt(first[0]);
        int m = Integer.parseInt(first[1]);

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().trim().toCharArray();
        }

        int[] queue = new int[m];

        for (int i = 0; i < n; i++) {
            int head = 0;
            int tail = 0;

            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'o') {
                        queue[tail++] = j;
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && grid[i - 1][j] == 'o') {
                        grid[i][j] = 'o';
                        queue[tail++] = j;
                    }
                }
            }

            while (head < tail) {
                int j = queue[head++];

                if (i + 1 < n && grid[i + 1][j] == '#') {
                    if (j > 0 && grid[i][j - 1] == '.') {
                        grid[i][j - 1] = 'o';
                        queue[tail++] = j - 1;
                    }
                    if (j + 1 < m && grid[i][j + 1] == '.') {
                        grid[i][j + 1] = 'o';
                        queue[tail++] = j + 1;
                    }
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (char[] row : grid) {
            out.append(row).append('\n');
        }
        System.out.print(out);
    }
}
